"""Seven Core clans: Discipline access, full Bane and clan Compulsion rules."""
import json,sys
from pathlib import Path
repo=Path(__file__).resolve().parent.parent;work=Path(sys.argv[1])
source=next(s for s in json.loads((work/'pages/manifest.json').read_text(encoding='utf-8')) if s['id']=='core-v5')
def add(slug,name,page,discs,english_discs,bane,bane_en,compulsion,compulsion_en,comp_page=212):
 pages=list(dict.fromkeys([page,comp_page]+([213] if slug=='tremere' else [])))
 descriptions={}
 for locale,ds,b,c in [('pt-BR',discs,bane,compulsion),('en',english_discs,bane_en,compulsion_en)]:
  descriptions[locale]=[
   {'title':'Disciplinas de Clã' if locale=='pt-BR' else 'Clan Disciplines','text':ds},
   {'title':'Perdição (Fraqueza)' if locale=='pt-BR' else 'Bane','text':b},
   {'title':'Compulsão do Clã' if locale=='pt-BR' else 'Clan Compulsion','text':c},
   {'title':'Uso e referência' if locale=='pt-BR' else 'Use and reference','text':('A Gravidade da Perdição depende da Potência de Sangue; não é um valor fixo escolhido pelo clã. Perdição e Compulsão são regras distintas: observe seus gatilhos, duração e penalidades. Esta é a versão do Livro Básico fornecido. A consulta não aplica penalidades temporárias nem altera textos pessoais da ficha. A história e os arquétipos do clã continuam na biblioteca; os poderes têm descrições próprias.' if locale=='pt-BR' else 'Bane Severity depends on Blood Potency; it is not a fixed value assigned by clan. Bane and Compulsion are distinct rules: observe their triggers, duration and penalties. This is the supplied Core Rulebook version. Consultation does not apply temporary penalties or alter personal sheet text. Clan history and archetypes remain in the library; powers have their own descriptions.')}
  ]
 entry={'id':'clan-'+slug,'kind':'clan','names':{'pt-BR':name,'en':'Malkavian' if slug=='malkavian' else name},'aliases':[name]+(['Malkaviano','Malkavian'] if slug=='malkavian' else []),'versions':[{'id':'clan-'+slug+'-core-v5','book':'core-v5','sourceTitle':'Livro Básico V5, pp. '+', '.join(str(p-2) for p in pages),'sourceLanguage':'pt-BR','pdfSha256':source['sha256'],'pages':[{'pdfPage':p,'printedPage':p-2} for p in pages],'descriptions':descriptions}]}
 (repo/'scripts/reviewed-content'/('core-clan-'+slug+'.json')).write_text(json.dumps(entry,ensure_ascii=False,indent=2),encoding='utf-8')
add('brujah','Brujah',69,
'Celeridade, Potência e Presença. Velocidade e força permitem atacar, subjugar e escapar; Presença influencia multidões, intimida e atrai vítimas.',
'Celerity, Potence and Presence. Speed and strength allow attacks, restraint and escape; Presence influences crowds, intimidates and attracts victims.',
'Seu Sangue ferve com fúria contida. Subtraia dados iguais à Gravidade da Perdição de qualquer parada para resistir a frenesi de fúria. Essa redução não pode deixar a parada com menos de 1 dado. A regra não estende essa penalidade aos testes de frenesi de fome ou terror.',
'Their Blood boils with suppressed anger. Subtract Bane Severity dice from any pool resisting fury frenzy. This reduction cannot leave fewer than 1 die. This rule does not extend that penalty to hunger or terror frenzy tests.',
'Rebelião: opõe-se ao que percebe como status quo, seja um líder, uma opinião ou a tarefa esperada. Sofre −2 dados em todas as rolagens até contrariar ordens reais ou percebidas, ou expectativas reais ou presumidas. Encerra ao fazer alguém mudar de ideia, pela força se necessário, ou ao fazer o oposto do esperado.',
'Rebellion: opposes the perceived status quo, whether a leader, an opinion or an expected task. Suffer −2 dice on all rolls until defying real or perceived orders, or actual or assumed expectations. It ends after making someone change their mind, by force if necessary, or doing the opposite of what was expected.')
add('gangrel','Gangrel',75,
'Animalismo, Fortitude e Proteanismo. O contato com animais, a resistência sobrenatural e a mudança corporal sustentam a existência predatória.',
'Animalism, Fortitude and Protean. Animal communion, supernatural endurance and bodily transformation support a predatory existence.',
'Durante um frenesi, manifesta aspectos animalescos em número igual à Gravidade da Perdição: aparência, odor ou comportamento. Persistem por mais uma noite após o frenesi. Cada aspecto reduz um Atributo em 1 ponto; o Narrador escolhe conforme o traço. Língua bifurcada ou odor de urso podem reduzir Carisma; orelhas de morcego podem reduzir Determinação pela distração. Na dúvida, reduza Inteligência ou Manipulação. Ao Curtir a Onda voluntariamente, pode escolher manifestar apenas um aspecto e sofrer apenas uma penalidade em um Atributo.',
'During frenzy, manifest animal features equal in number to Bane Severity: physical traits, odors or behavior. They last one additional night after the frenzy. Each feature reduces one Attribute by 1; the Storyteller chooses according to the feature. A forked tongue or bear odor may reduce Charisma; bat ears may reduce Resolve through distraction. When in doubt, reduce Intelligence or Manipulation. When voluntarily Riding the Wave, choose to manifest just one feature and suffer only one Attribute penalty.',
'Impulsos Ferais: regride a um estado animal; falar é difícil, roupas incomodam e disputas parecem exigir presas e garras. Por uma cena, sofre −3 dados nas rolagens envolvendo Manipulação e Inteligência e só consegue pronunciar sentenças monossilábicas.',
'Feral Impulses: regresses to an animal state; speech is difficult, clothes uncomfortable and disputes seem to require fangs and claws. For one scene, suffer −3 dice on rolls involving Manipulation and Intelligence and speak only in monosyllabic sentences.')
add('malkavian','Malkaviano',81,
'Auspícios, Dominação e Ofuscação. Percepção sobrenatural, influência mental e ocultação permitem observar, manipular e aproximar-se das vítimas.',
'Auspex, Dominate and Obfuscate. Supernatural perception, mental influence and concealment allow observation, manipulation and access to victims.',
'A aflição sobrenatural pode se manifestar como delírios, visões de clareza terrível ou outra experiência definida na criação pelo jogador e Narrador. Ao sofrer uma Falha Bestial ou uma Compulsão, aplique uma penalidade igual à Gravidade da Perdição a uma categoria de paradas — Física, Social ou Mental — durante toda a cena. A categoria e a natureza da aflição são definidas na criação. Essa penalidade se soma às penalidades da própria Compulsão.',
'The supernatural affliction may manifest as delusions, visions of terrible clarity or another experience defined at creation by player and Storyteller. When suffering a Bestial Failure or a Compulsion, apply a Bane Severity penalty to one pool category — Physical, Social or Mental — for the entire scene. Define the category and nature of the affliction at creation. This penalty stacks with the Compulsion’s own penalties.',
'Delírio: seus dons extrassensoriais distorcem mente e percepções com possíveis verdades, presságios ou delírios da Fome. Continua funcional, mas sofre −2 dados por uma cena em rolagens envolvendo Destreza, Manipulação, Autocontrole e Raciocínio, além dos testes para resistir ao frenesi de terror.',
'Delusion: extrasensory gifts distort mind and perception with possible truths, omens or Hunger-driven delusions. Remains functional but suffers −2 dice for one scene on rolls involving Dexterity, Manipulation, Composure and Wits, as well as tests resisting terror frenzy.')
add('nosferatu','Nosferatu',87,
'Animalismo, Ofuscação e Potência. Animais e servos ajudam a reunir informações; ocultação permite circular e caçar; força sobrenatural subjuga inimigos.',
'Animalism, Obfuscate and Potence. Animals and servants gather information; concealment permits movement and hunting; supernatural strength subdues enemies.',
'Possui o Defeito Repulsivo (−2) e nunca pode aumentar seu valor na Qualidade Visual. Tentativas de esconder suas deformidades sofrem uma penalidade de dados igual à Gravidade da Perdição, incluindo poderes como Máscara de Mil Faces e Disfarce do Impostor. Ser visto não é, por si só, uma quebra automática da Máscara: a maioria parece grotesca e aterrorizante, mas nem sempre de modo obviamente sobrenatural.',
'Has the Repulsive (−2) Flaw and can never increase their Looks Merit rating. Attempts to hide their deformities suffer a Bane Severity dice penalty, including powers such as Mask of a Thousand Faces and Impostor’s Guise. Being seen is not by itself an automatic Masquerade breach: most appear grotesque and frightening, but not always obviously supernatural.',
'Criptofilia: uma fome de segredos quase tão forte quanto a de sangue o domina. Recusa compartilhar segredos, exceto em troca estrita por segredos maiores. Ações que não sirvam para descobrir um segredo sofrem −2 dados. Encerra quando aprende um segredo grande o bastante para ser útil; compartilhá-lo depois é opcional.',
'Cryptophilia: a hunger for secrets almost as strong as the thirst for blood takes over. Refuses to share secrets except in strict exchange for greater secrets. Actions not directed toward learning a secret suffer −2 dice. Ends after learning a secret important enough to be useful; sharing it afterward is optional.')
add('toreador','Toreador',93,
'Auspícios, Celeridade e Presença. Sentidos refinados, velocidade sobrenatural e domínio emocional favorecem a percepção, a arte e a caça social.',
'Auspex, Celerity and Presence. Refined senses, supernatural speed and emotional influence support perception, art and social hunting.',
'Sofre na ausência de beleza. Num ambiente que considera menos que belo, reduza suas paradas para acionar Disciplinas em dados iguais à Gravidade da Perdição. O Narrador decide a aplicação conforme o senso estético da personagem, considerando ambiente, roupas e pessoas usadas como fonte de sangue. Mesmo gostos voltados ao grotesco não tornam automaticamente belas todas as ruas comuns. Essa obsessão também faz com que Falhas Bestiais frequentemente provoquem o transe de arrebatamento descrito na Compulsão.',
'Suffers in the absence of beauty. In surroundings considered less than beautiful, reduce Discipline activation pools by Bane Severity dice. The Storyteller applies this according to the character’s aesthetic sense, including surroundings, clothing and blood dolls. Even a taste for the grotesque does not make every ordinary street automatically beautiful. This obsession also means Bestial Failures often bring the rapturous trance described by the Compulsion.',
'Obsessão: escolha algo singularmente belo — pessoa, canção, obra de arte, mancha de sangue ou até a aurora. Quase não consegue desviar a atenção e, ao conversar, só fala do objeto. Outras ações sofrem −2 dados. Dura até deixar de perceber o objeto ou até o fim da cena.',
'Obsession: choose something uniquely beautiful — a person, song, artwork, bloodstain or even dawn. Can barely turn attention away and talks only about it when addressed. Other actions suffer −2 dice. Lasts until the object can no longer be perceived or the scene ends.')
add('tremere','Tremere',99,
'Auspícios, Dominação e Feitiçaria de Sangue. Percepção identifica auras e vestígios; influência mental favorece conhecimento e controle; magia do sangue oferece poderes e Rituais aprendidos separadamente.',
'Auspex, Dominate and Blood Sorcery. Perception identifies auras and traces; mental influence supports knowledge and control; blood magic offers powers and separately learned Rituals.',
'Depois da queda de Viena, seu Vitae deixou de criar Laços de Sangue em outros Membros. Isso não impede que o Tremere seja Enlaçado por vampiros de outros clãs. Ainda pode Enlaçar mortais e carniçais, mas formar o Laço exige um número adicional de ingestões de seu Vitae igual à Gravidade da Perdição. Essa é a versão presente no Livro Básico fornecido, sem substituir por uma variante de outro suplemento.',
'After Vienna’s fall, Tremere Vitae can no longer create Blood Bonds in other Kindred. This does not prevent a Tremere from being Bound by vampires of other clans. Mortals and ghouls can still be Bound, but forming the Bond requires additional drinks of their Vitae equal to Bane Severity. This is the supplied Core Rulebook version, without substituting another supplement’s variant.',
'Perfeccionismo: repete tarefas por considerar insuficiente qualquer resultado que não seja excepcional. Sofre −2 dados em todas as paradas até obter uma vitória crítica numa rolagem de Habilidade ou até o fim da cena. Para uma ação repetida, a penalidade cai para −1; numa segunda repetição da mesma ação, é removida por completo.',
'Perfectionism: repeats tasks because anything short of an exceptional result feels inadequate. Suffer −2 dice on all pools until achieving a critical win on a Skill roll or the scene ends. On repeating an action, reduce its penalty to −1; on a second repetition of the same action, remove it entirely.')
add('ventrue','Ventrue',104,
'Dominação, Fortitude e Presença. Controle mental e devoção sustentam a autoridade; resistência sobrenatural permite sobreviver aos ataques contra ela.',
'Dominate, Fortitude and Presence. Mental control and devotion support authority; supernatural endurance survives attacks against it.',
'Só tolera facilmente sangue de mortais de um tipo preferido, definido na personagem: características de origem, aparência, ocupação ou experiência são exemplos. Determinação + Percepção, Dificuldade 4 ou maior, permite identificar se um mortal possui o sangue desejado. Para se alimentar de um mortal fora da preferência, gaste Força de Vontade igual à Gravidade da Perdição para não vomitar o sangue. A preferência não é uma lista universal imposta a todos os Ventrue.',
'Readily tolerates only mortal blood of a preferred type defined for the character: background, appearance, occupation or experience are examples. Resolve + Awareness at Difficulty 4 or higher identifies whether a mortal has the desired blood. Feeding from a mortal outside the preference requires spending Willpower equal to Bane Severity to avoid vomiting the blood. The preference is not one universal list imposed on every Ventrue.',
'Arrogância: precisa assumir o controle e fazer alguém obedecer a uma ordem. Ações sem relação direta com liderança sofrem −2 dados. Encerra quando a ordem é obedecida, desde que a obediência não seja obtida por meios sobrenaturais, como Dominação.',
'Arrogance: must take control and make someone obey an order. Actions not directly related to leadership suffer −2 dice. Ends when the order is obeyed, provided obedience was not obtained through supernatural means such as Dominate.',213)
print('Seven Core clan rule references: full Bane and Compulsion mechanics in both languages')
